from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 4 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.pop()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append((color, cells))
    return comps


def _shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return tuple(sorted((r-r0, c-c0) for r, c in cells))


def _l_corner(cells):
    """Return the corner and inward signs of a one-cell-thick L component."""
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    if r0 == r1 or c0 == c1 or len(cells) != (r1-r0+1)+(c1-c0+1)-1:
        return None
    cellset = set(cells)
    for cr, sr in ((r0, 1), (r1, -1)):
        for cc, sc in ((c0, 1), (c1, -1)):
            expected = {(cr, c) for c in range(min(cc, c1) if cc == c0 else c0,
                                                  max(cc, c0) + 1 if cc == c1 else c1 + 1)}
            # Build the two arms explicitly; their union must equal this component.
            expected = {(cr, c) for c in range(c0, c1+1)} | {(r, cc) for r in range(r0, r1+1)}
            # The corner must be an extreme on both axes, and the L must occupy
            # the selected pair of bbox edges, not the opposite pair.
            if (cr, cc) in cellset:
                arm_h = {(cr, c) for c in range(c0, c1+1)}
                arm_v = {(r, cc) for r in range(r0, r1+1)}
                if cellset == arm_h | arm_v:
                    return cr, cc, sr, sc
    return None


def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid)
    candidates = []
    for color, cells in comps:
        corner = _l_corner(cells)
        if corner is not None:
            candidates.append((len(cells), color, cells, corner))
    if not candidates:
        return out
    _, marker_color, marker, (cr, cc, sr, sc) = max(candidates, key=lambda x: x[0])

    # Match identical oriented shapes on the inward and outward sides of the L.
    by_shape = {}
    for color, cells in comps:
        if set(cells) == set(marker):
            continue
        by_shape.setdefault(_shape(cells), []).append((color, cells))
    for group in by_shape.values():
        inside = []
        outside = []
        for color, cells in group:
            is_inside = all((r-cr)*sr > 0 and (c-cc)*sc > 0 for r, c in cells)
            (inside if is_inside else outside).append((color, cells))
        if inside and outside:
            # The copy outside the L's inward quadrant is the one to recolor.
            for color, cells in outside:
                for r, c in cells:
                    out[r][c] = marker_color
    return out

