def transform(grid):
    """Copy the embedded horizontal pattern around every isolated marker."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Find the contiguous, multi-cell motif (the only dense non-background run).
    motif = None
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start >= 2 and (motif is None or c - start > len(motif[2])):
                motif = (r, start, row[start:c])
    if motif is None:
        return [row[:] for row in grid]
    mr, mc, pattern = motif
    motif_colors = set(pattern)
    out = [row[:] for row in grid]
    # An isolated color not used by the motif marks the center of each copy.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    marker_colors = [v for v, n in counts.items() if v != bg and v not in motif_colors and n > 0]
    # On these puzzles all markers share one color; preserve their positions while stamping.
    for r, row in enumerate(grid):
        if r == mr:
            continue
        for c, v in enumerate(row):
            if v in marker_colors:
                left = c - len(pattern) // 2
                for j, color in enumerate(pattern):
                    if 0 <= left + j < w:
                        out[r][left + j] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    nonbg = Counter({v:n for v,n in counts.items() if v != bg})
    marker = nonbg.most_common(1)[0][0]
    # The colored exemplar is the longest straight run of non-background,
    # non-marker cells. It may be horizontal or vertical.
    best = None
    for dr, dc in ((0,1),(1,0)):
        for r in range(h):
            for c in range(w):
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] != bg and grid[pr][pc] != marker:
                    continue
                rr, cc = r, c
                vals=[]
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg and grid[rr][cc] != marker:
                    vals.append(grid[rr][cc]); rr += dr; cc += dc
                if len(vals) >= 2 and (best is None or len(vals) > len(best[0])):
                    best=(vals,dr,dc)
    if best is None:
        return [row[:] for row in grid]
    pattern, dr, dc = best
    out=[row[:] for row in grid]
    off=len(pattern)//2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i,color in enumerate(pattern):
                    rr=r+(i-off)*dr; cc=c+(i-off)*dc
                    if 0 <= rr < h and 0 <= cc < w:
