def transform(grid):
    """Mark every monochromatic full row or column with color 2."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rows = {i for i, row in enumerate(grid) if all(v == row[0] for v in row)}
    cols = {j for j in range(w) if all(grid[i][j] == grid[0][j] for i in range(h))}
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if i in rows or j in cols:
                out[i][j] = 2
    return out

from collections import deque


def transform(grid):
    """Return a 3x3 tile in the color of the largest connected region."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    largest = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            seen[r][c] = True
            q = deque([(r, c)])
            component = [(r, c)]
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
                        component.append((yy, xx))
            if len(component) > len(largest):
                largest = component
                largest_color = color
    return [[largest_color] * 3 for _ in range(3)]

