def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
            minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
            objects.append((minc, minr, color, cells, maxr-minr+1, maxc-minc+1))
    objects.sort(key=lambda o: (o[0], o[1]))
    out=[[0]*w for _ in range(h)]
    top=left=0
    prev_h=prev_w=None
    for i, (minc,minr,color,cells,oh,ow) in enumerate(objects):
        if i:
            top += prev_h - 1
            left += prev_w - 1
        for y,x in cells:
            yy=top+(y-minr); xx=left+(x-minc)
            if 0 <= yy < h and 0 <= xx < w:
                out[yy][xx]=color
        prev_h,prev_w=oh,ow
    return out

def transform(grid):
    # A horizontal row of 1s is the ground. Markers build fixed-height
    # columns upward: color 2 has height 4, and color 8 has height 3.
    out = [row[:] for row in grid]
    ground_rows = [r for r, row in enumerate(grid) if 1 in row and any(v not in (0, 1) for v in row)]
    if not ground_rows:
        return out
    ground = ground_rows[-1]
    heights = {2: 4, 8: 3}
    for c, color in enumerate(grid[ground]):
        height = heights.get(color, 0)
        for offset in range(1, min(height, ground) + 1):
            out[ground - offset][c] = color if offset == height else 1
    return out

def transform(grid):
    """Complete vertical channels at gaps in horizontal bars."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    if h == 0:
        return out
    # The channels are identified by their colored vertical stems touching
    # the bottom edge. Horizontal gaps along each channel set band colors.
    for c in range(w):
        stem = grid[h - 1][c]
        if stem == 0:
            continue
        markers = []
        for r in range(h):
            if grid[r][c] != 0:
                continue
            left = next((grid[r][j] for j in range(c - 1, -1, -1) if grid[r][j] != 0), 0)
            right = next((grid[r][j] for j in range(c + 1, w) if grid[r][j] != 0), 0)
            if left != 0 and left == right:
                markers.append((r, left))
        if not markers:
            continue
        start = 0
        for r, color in markers:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1
        # Preserve the stem color below the final horizontal boundary.
        for rr in range(start, h):
            out[rr][c] = grid[rr][c] if grid[rr][c] != 0 else stem
    return out

from collections import Counter, defaultdict

def transform(grid):
    """Complete the smallest consistent periodic stripe pattern."""
    h, w = len(grid), len(grid[0])
    projections = {
        "row": lambda r, c: r,
        "col": lambda r, c: c,
        "sum": lambda r, c: r + c,
        "diff": lambda r, c: c - r,
    }
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]
    best = None
    for name, keyfn in projections.items():
        groups = defaultdict(list)
        for r, c, color in points:
            groups[keyfn(r, c)].append(color)
        # Dense, same-colored parallel lines identify the pattern's axis.
        cohesion = sum(len(vals) ** 2 for vals in groups.values())
        purity = sum(max(Counter(vals).values()) for vals in groups.values())
        score = (cohesion, purity)
        if best is None or score > best[0]:
            best = (score, name, keyfn, groups)
    _, name, keyfn, groups = best
    maxp = max(h, w)
    period = maxp
    for p in range(1, maxp + 1):
        residues = {}
        valid = True
        for k, vals in groups.items():
            color = Counter(vals).most_common(1)[0][0]
            residue = k % p
            if residue in residues and residues[residue] != color:
                valid = False
                break
            residues[residue] = color
        if valid:
            period = p
            break
    counts = Counter(color for _, _, color in points)
    default = counts.most_common(1)[0][0]
    residue_colors = {}
    for k, vals in groups.items():
        residue_colors[k % period] = Counter(vals).most_common(1)[0][0]
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            residue = keyfn(r, c) % period
            row.append(residue_colors.get(residue, default))
        out.append(row)
    return out

