def transform(grid):
    """Move the non-background object up against the full 2-line; mark its far edge with 8."""
    a=[list(row) for row in grid]
    h,w=len(a),len(a[0])
    line=None
    for r,row in enumerate(a):
        if all(v==2 for v in row):
            line=(0,r); break
    if line is None:
        for c in range(w):
            if all(a[r][c]==2 for r in range(h)):
                line=(1,c); break
    if line is None:
        return a
    axis,d=line
    counts=Counter(v for row in a for v in row if v!=2)
    if not counts:
        return a
