    colors=[v for v in counts if v!=bg]
    if not colors:
        return a
    # The task's movable pattern is the non-background, non-divider color.
    color=max(colors,key=lambda v:counts[v])
    pts=[(r,c) for r in range(h) for c in range(w) if a[r][c]==color]
    if not pts:
        return a
    coords=[r if axis==0 else c for r,c in pts]
