    if moved:
        moved_coords=[r if axis==0 else c for r,c in moved]
        marker=(min(moved_coords)-1) if before else (max(moved_coords)+1)
        if 0<=marker<(h if axis==0 else w):
            if axis==0:
                out[marker]=[8]*w
            else:
                for r in range(h): out[r][marker]=8
    return out

