            for c in range(w):
                v = int(grid[r][c] == color)
                run += v
                row_pref[r][c + 1] = run
                col_pref[r + 1][c] = col_pref[r][c] + v
                pref[r + 1][c + 1] = pref[r][c + 1] + run

