def transform(grid):
    """Reverse the color order of nested, nonzero shapes in each component."""
    height, width = len(grid), len(grid[0])
    seen = set()
    output = [row[:] for row in grid]

    for row in range(height):
        for col in range(width):
            if grid[row][col] == 0 or (row, col) in seen:
                continue

            component = []
            queue = deque([(row, col)])
            seen.add((row, col))
            while queue:
                r, c = queue.popleft()
                component.append((r, c))
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if (0 <= nr < height and 0 <= nc < width
                            and grid[nr][nc] != 0 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        queue.append((nr, nc))

            # Larger color bounding boxes are outer layers; smaller ones are inner.
            bounds = {}
            for r, c in component:
                color = grid[r][c]
                if color not in bounds:
                    bounds[color] = [r, r, c, c]
                else:
                    box = bounds[color]
                    box[0] = min(box[0], r)
                    box[1] = max(box[1], r)
                    box[2] = min(box[2], c)
                    box[3] = max(box[3], c)

            colors = sorted(
                bounds,
                key=lambda color: (bounds[color][1] - bounds[color][0] + 1)
                               * (bounds[color][3] - bounds[color][2] + 1),
                reverse=True,
            )
            recolor = {colors[i]: colors[-1 - i] for i in range(len(colors))}
            for r, c in component:
                output[r][c] = recolor[grid[r][c]]

    return output

