def transform(grid):
    h, w = len(grid), len(grid[0])
    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    guide = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    if not eight or not guide:
        return [row[:] for row in grid]

    # The colored guide is a small shape. Each guide cell corresponds to
    # one uniformly scaled square in the larger 8-shaped object.
    area = len(eight) / len(guide)
    scale = int(round(math.sqrt(area)))
    if scale < 1 or scale * scale * len(guide) != len(eight):
        return [row[:] for row in grid]
    r0 = min(r for r, _ in eight)
    c0 = min(c for _, c in eight)
    units = set()
    for r, c in eight:
        units.add(((r-r0)//scale, (c-c0)//scale))
    # Verify that each unit is a full scale-by-scale square.
    for ur, uc in units:
        if any(grid[r0+ur*scale+dr][c0+uc*scale+dc] != 8
               for dr in range(scale) for dc in range(scale)):
            return [row[:] for row in grid]

    gr0 = min(r for r, _, _ in guide)
    gc0 = min(c for _, c, _ in guide)
    source = {(r-gr0, c-gc0): color for r, c, color in guide}
    target_r0 = min(r for r, _ in units)
    target_c0 = min(c for _, c in units)
    target = {(r-target_r0, c-target_c0) for r, c in units}

    # Find the rotation/reflection that makes the guide silhouette match the
    # 8-cell silhouette, then carry its colors along with it.
    H = max(r for r, _ in source) + 1
    W = max(c for _, c in source) + 1
    for flip in (False, True):
        for turns in range(4):
            transformed = {}
            cur_h, cur_w = H, W
            for (r, c), color in source.items():
                rr, cc = (r, cur_w-1-c) if flip else (r, c)
                hh, ww = cur_h, cur_w
                for _ in range(turns):
                    rr, cc = cc, hh-1-rr
                    hh, ww = ww, hh
                transformed[(rr, cc)] = color
            minr = min(r for r, _ in transformed)
            minc = min(c for _, c in transformed)
            norm = {(r-minr, c-minc) for r, c in transformed}
            if norm == target:
                color_at = {(r-minr, c-minc): color for (r, c), color in transformed.items()}
                out = [row[:] for row in grid]
                for ur, uc in units:
                    color = color_at[(ur-target_r0, uc-target_c0)]
                    for dr in range(scale):
                        for dc in range(scale):
                            out[r0+ur*scale+dr][c0+uc*scale+dc] = color
                return out
    return [row[:] for row in grid]

