def transform(grid):
    """Tile the 8-cells into 2x2 blocks and L triominoes, then color tile types."""
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # The demonstrations identify these three L orientations. A filled 2x2
    # block is color 1; Ls missing top-left, bottom-left, or top-right are 2,3,4.
    orientations = [((0, 0), 2), ((1, 0), 3), ((0, 1), 4)]
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            if square <= cells:
                tiles.append((square, 1))
            for (mr, mc), color in orientations:
                piece = square - {(r + mr, c + mc)}
                if piece <= cells:
                    tiles.append((piece, color))

    # Exact-cover search. Use the most constrained remaining cell first.
    by_cell = {cell: [] for cell in cells}
    for piece, color in tiles:
        for cell in piece:
            by_cell[cell].append((piece, color))

    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(piece <= remaining for piece, _ in by_cell[p]))
        for piece, color in by_cell[cell]:
            if piece <= remaining:
                rest = solve(remaining - piece)
                if rest is not None:
                    return [(piece, color)] + rest
        return None

    tiling = solve(cells)
    if tiling is None:
        raise ValueError("No demonstrated tile decomposition found")
    out = [[0 for _ in range(w)] for _ in range(h)]
    for piece, color in tiling:
        for r, c in piece:
            out[r][c] = color
    return out

