    """Complete each colored partial copy of the color-4 template."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    template = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 4}
    if not template:
        return out
    min_r = min(r for r, c in template)
    min_c = min(c for r, c in template)
    shape = {(r - min_r, c - min_c) for r, c in template}
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
