                    if ar < 0 or ac < 0 or ar + sh > h or ac + sw > w:
                        continue
                    cells = {(ar + sr, ac + sc) for sr, sc in shape}
                    covered = remaining & cells
                    if len(covered) >= 2:
                        candidates[(ar, ac)] = (covered, cells)
