                    g[rr][c] = ray_color
                    rr += 1
            elif edge == 'bottom':
                c=k
                rr=h-2
                while rr >= 0:
                    if g[rr][c] == ray_color:
                        g[rr][c] = 4
                        break
                    g[rr][c] = ray_color
                    rr -= 1
            elif edge == 'left':
                r=k
                cc=1
                while cc < w:
                    if g[r][cc] == ray_color:
                        g[r][cc] = 4
                        break
                    g[r][cc] = ray_color
                    cc += 1
            else: # right
                r=k
                cc=w-2
                while cc >= 0:
                    if g[r][cc] == ray_color:
                        g[r][cc] = 4
                        break
                    g[r][cc] = ray_color
                    cc -= 1
    return g

from collections import deque


def transform(grid):
    """Color the one-cell rims of enclosed zero regions and their outer rims."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    n4 = ((-1, 0), (1, 0), (0, -1), (0, 1))
    n8 = tuple((dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1)
               if dr != 0 or dc != 0)

    # Label each 4-connected component of 1s.
    one_label = {}
    next_label = 0
    for r in range(h):
        for c in range(w):
            if out[r][c] != 1 or (r, c) in one_label:
                continue
            stack = [(r, c)]
            one_label[(r, c)] = next_label
            while stack:
                y, x = stack.pop()
                for dy, dx in n4:
                    z = (y + dy, x + dx)
                    if (0 <= z[0] < h and 0 <= z[1] < w
                            and out[z[0]][z[1]] == 1 and z not in one_label):
                        one_label[z] = next_label
                        stack.append(z)
            next_label += 1

    # Find 4-connected zero regions. A region not touching the grid edge is a hole.
    unseen = {(r, c) for r in range(h) for c in range(w) if out[r][c] == 0}
    holes = []
    outside = []
    while unseen:
        start = unseen.pop()
        stack = [start]
        region = {start}
        touches_edge = (start[0] == 0 or start[0] == h - 1 or
                        start[1] == 0 or start[1] == w - 1)
        while stack:
            y, x = stack.pop()
            for dy, dx in n4:
                z = (y + dy, x + dx)
                if z in unseen:
                    unseen.remove(z)
                    region.add(z)
                    stack.append(z)
                    if (z[0] == 0 or z[0] == h - 1 or
                            z[1] == 0 or z[1] == w - 1):
                        touches_edge = True
        (outside if touches_edge else holes).append(region)

    # A 1-component is active if it bounds at least one hole.
    active = set()
    for hole in holes:
        for r, c in hole:
            for dr, dc in n4:
                pos = (r + dr, c + dc)
                if pos in one_label:
                    active.add(one_label[pos])

    # Paint the inner one-cell rim of every hole with 3.
    for hole in holes:
        for r, c in hole:
            if any(0 <= r + dr < h and 0 <= c + dc < w
                   and out[r + dr][c + dc] == 1 for dr, dc in n8):
                out[r][c] = 3

    # Paint the outer one-cell rim of active 1-components with 2.
    for region in outside:
        for r, c in region:
            if any(0 <= r + dr < h and 0 <= c + dc < w
                   and one_label.get((r + dr, c + dc)) in active
                   for dr, dc in n8):
                out[r][c] = 2
    return out

from collections import Counter

def transform(grid):
    """Copy the marked shape onto every all-zero matching placement."""
    counts = Counter(v for row in grid for v in row)
    backgrounds = {value for value, _ in counts.most_common(2)}
    markers = set(counts) - backgrounds
    if not markers:
        return [row[:] for row in grid]
    marker = next(iter(markers))
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == marker]
    if not points:
        return [row[:] for row in grid]
    min_r, max_r = min(r for r, _ in points), max(r for r, _ in points)
    min_c, max_c = min(c for _, c in points), max(c for _, c in points)
    mask = [(r - min_r, c - min_c) for r, c in points]
    height, width = max_r - min_r + 1, max_c - min_c + 1
    out = [row[:] for row in grid]
    for r in range(len(grid) - height + 1):
        for c in range(len(grid[0]) - width + 1):
            if all(grid[r + dr][c + dc] == 0 for dr, dc in mask):
                for dr, dc in mask:
                    out[r + dr][c + dc] = marker
    return out

from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    foreground = [v for v in counts if v != bg]
    if not foreground:
        return [row[:] for row in grid]
    outside_color = max(foreground, key=lambda v: counts[v])
    fill = 4
    seen = set()
    out = [row[:] for row in grid]
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != bg or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            component = []
            while q:
                r, c = q.popleft()
                component.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            r0 = min(r for r, c in component); r1 = max(r for r, c in component)
            c0 = min(c for r, c in component); c1 = max(c for r, c in component)
            touches = set()
            for r, c in component:
                if r == 0: touches.add('top')
                if r == h - 1: touches.add('bottom')
                if c == 0: touches.add('left')
                if c == w - 1: touches.add('right')
            # A hole is normally enclosed by the outline. Treat the canvas edge
            # as one wall too when it completes a rectangular enclosure.
            edge_cavity = (len(touches) == 1 and r1-r0+1 >= 2 and c1-c0+1 >= 2
                           and len(component) == (r1-r0+1)*(c1-c0+1))
            is_rectangle = len(component) == (r1-r0+1)*(c1-c0+1)
            if is_rectangle and (not touches or edge_cavity):
                for r, c in component:
                    out[r][c] = fill
    return out

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (g[r][c] == 0 and g[r-1][c] == 2 and g[r+1][c] == 2
                    and g[r][c-1] == 2 and g[r][c+1] == 2):
                centers.append((r, c))
    # Join the facing tips of any two aligned plus-shaped objects.
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i+1:]:
            if r1 == r2 and c1 < c2:
                for c in range(c1 + 2, c2 - 1):
                    if g[r1][c] == 0:
                        g[r1][c] = 1
            elif c1 == c2 and r1 < r2:
                for r in range(r1 + 2, r2 - 1):
                    if g[r][c1] == 0:
                        g[r][c1] = 1
    return g

def transform(grid):
    """Expand a centered marker into diagonal rays and a periodic inner lattice."""
    n = len(grid[0])
    center = n // 2
    out = [[0 for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            distance = abs(c - center)
            if distance == r:
                out[r][c] = 2
            elif distance < r and (c - r - center) % 4 == 0:
                out[r][c] = 1
    return out

